function normalizarTelefono(raw) {
  let s = String(raw ?? '').trim();
  const teniaMas = s.startsWith('+');
  s = s.replace(/\D/g, '');
  if (!teniaMas && s.startsWith('00')) s = s.slice(2);
  if (/^[6789]\d{8}$/.test(s)) s = '34' + s;
  return {
    e164: s ? '+' + s : '',
    wa_id: s,                                   // como lo quiere Meta: solo digitos
    nacional: s.startsWith('34') ? s.slice(2) : s,
    valido: s.length >= 8 && s.length <= 15,
  };
}

const sinAcentos = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

function prefijoDeReferencia(ref) {
  const m = String(ref ?? '').toUpperCase().match(/[A-Z]{2}/);
  return m ? m[0] : '';
}

// De varias referencias posibles (la de la cartera, la que manda el agente, la
// del lead de ese telefono), la primera que tiene comercial (BN/OR -> Carmen,
// CS/VR -> Gisela). Asi un numero de enlace ("26699629-A") nunca deja el aviso
// sin comercial si hay otra referencia buena.
function referenciaBuena(...candidatas) {
  const limpias = candidatas.map(x => String(x ?? '').toUpperCase().trim()).filter(Boolean);
  return limpias.find(x => ASESORA_POR_PREFIJO[prefijoDeReferencia(x)]) || limpias[0] || '';
}

// Como se le nombra al cliente a quien se encarga: la asesora de la zona por su
// nombre (Carmen o Gisela). Laurence es de la oficina, no "asesora de la zona".
function quienSeEncarga(nombre, zona) {
  const n = String(nombre ?? '').trim();
  const z0 = String(zona ?? '').split(' / ')[0].trim();
  const z = /^benicasim$/i.test(z0) ? 'Benicàssim' : z0;
  if (['Carmen', 'Gisela'].includes(n)) return `${n}, la asesora de la zona${z ? ' de ' + z : ''}`;
  return n ? `${n}, de nuestro equipo` : 'nuestro equipo';
}

// Asesora por referencia y, si no hay, por municipio. Si no hay ninguna, Laurence.
function resolverAsesora(ref, municipio) {
  const prefijo = prefijoDeReferencia(ref);
  let asesora = ASESORA_POR_PREFIJO[prefijo] || null;
  if (!asesora && municipio) {
    const m = sinAcentos(municipio);
    for (const [clave, quien] of Object.entries(ASESORA_POR_MUNICIPIO)) {
      if (m.includes(clave)) { asesora = quien; break; }
    }
  }
  const final = asesora || 'Laurence';
  return { prefijo, asesora, conocida: !!asesora, destinatario: final, ...EQUIPO[final] };
}

// Alquiler o compra. Mismo criterio que el telefono: lo dice la operacion o la
// referencia acaba en -A.
function esAlquiler(referencia, operacion) {
  // La referencia manda: en Casagencia las que acaban en -A son de alquiler y las
  // de -V de venta. eGO a veces marca "Venta" una solicitud de Idealista de un
  // piso de alquiler (BN-C-126-A, 6-10-2026).
  const ref = String(referencia ?? '').trim();
  if (/-A$/i.test(ref)) return true;
  if (/-V$/i.test(ref)) return false;
  const o = String(operacion ?? '').toLowerCase();
  if (o.includes('alquiler') || o.includes('traspaso') || o.includes('rent')) return true;
  if (o.includes('venta') || o.includes('compra')) return false;
  return /-A$/i.test(String(referencia ?? '').trim());
}

function detectarPortal(remitente, asunto) {
  for (const p of PORTALES) {
    if (p.de.test(String(remitente ?? '')) || p.asunto.test(String(asunto ?? ''))) return p.nombre;
  }
  return 'Otro';
}

// Meta no admite saltos de linea, tabuladores ni mas de 4 espacios seguidos
// dentro de un parametro de plantilla: si los hay, rechaza el envio entero.
function paramPlantilla(texto, max = 700) {
  return String(texto ?? '')
    .replace(/[\r\n\t]+/g, ' · ')
    .replace(/ {2,}/g, ' ')
    .trim()
    .slice(0, max) || '-';
}

// Recorta un texto a `max` caracteres sin partir palabras (y con … si sobra).
function recortar(texto, max) {
  const t = String(texto ?? '').replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const corte = t.slice(0, max - 1);
  const espacio = corte.lastIndexOf(' ');
  return (espacio > max * 0.6 ? corte.slice(0, espacio) : corte).replace(/[\s,.;:·-]+$/, '') + '…';
}

// "2026-10-02" + "17:00" -> "jueves 2 de octubre a las 17:00"
function fechaLegible(fecha, hora) {
  const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto',
                 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const d = DateTime.fromFormat(String(fecha), 'yyyy-MM-dd', { zone: ZONA });
  if (!d.isValid) return `${fecha} ${hora || ''}`.trim();
  return `${DIAS[d.weekday - 1]} ${d.day} de ${MESES[d.month - 1]}` + (hora ? ` a las ${hora}` : '');
}

// "17:00" -> "5 de la tarde", "10:30" -> "10 y media de la mañana", "12:15" ->
// "12 y cuarto del mediodía". Para las plantillas que dicen "a las {{2}}".
function horaTexto(hora) {
  const m = String(hora ?? '').match(/^(\d{1,2}):(\d{2})/);
  if (!m) return String(hora ?? '');
  const h = Number(m[1]), min = Number(m[2]);
  if (h === 13 || h === 1) return `${m[1].padStart(2, '0')}:${m[2]}`;   // "a las una" no encaja
  const h12 = h % 12 || 12;
  const franja = h < 6 ? 'de la madrugada' : h < 12 ? 'de la mañana' : h === 12 ? 'del mediodía'
    : h < 21 ? 'de la tarde' : 'de la noche';
  const minutos = min === 0 ? '' : min === 30 ? ' y media' : min === 15 ? ' y cuarto' : `:${m[2]}`;
  return `${h12}${minutos} ${franja}`;
}

// "Si, tengo que vender el mio" -> true. "No", "no necesito" -> false.
function esAfirmativo(texto) {
  const t = sinAcentos(texto).trim();
  if (!t || /^(no\b|nop|para nada|ninguna|nada)/.test(t) || /\bno (necesito|tengo|hace falta)\b/.test(t)) return false;
  return /^(si\b|sí\b|claro|por supuesto|correcto|exacto)/.test(t) ||
    /\b(tengo|necesito|debo|tendria|tendre|hay) que vender\b|\bnecesito vender\b|\bvender (primero|antes|mi|el|la)\b/.test(t);
}

// Id del agente de Chatwoot de un comercial ('Carmen' -> 5). 0 si no tiene.
function agenteDe(nombre) {
  return Number(AGENTES_CHATWOOT[String(nombre ?? '').trim()] || 0);
}

function esPrueba(telefono) {
  const t = normalizarTelefono(telefono).wa_id;
  return !!t && (PRUEBAS.telefonos || []).includes(t);
}

// Lo nuevo de leads y eGO (primer WhatsApp a los leads, notas en eGO) solo
// actua de verdad con MODO_LEADS = 'real'; con los telefonos de prueba, siempre.
function leadsEnReal(telefono) {
  return MODO_LEADS === 'real' || esPrueba(telefono);
}


// ===========================================================================
// CARTERA · utilidades comunes de los nodos que leen la cartera
// ---------------------------------------------------------------------------
// La cartera de WhatsApp es la tabla wa_cartera de Postgres, que rellena cada
// hora [WA] 4 desde el MISMO feed de eGO que usa el telefono, pero completa:
// descripcion entera (la hoja del telefono la corta a 500 caracteres),
// superficie, caracteristicas en espanol y el enlace de la web de cada inmueble.
// La pestana "Direcciones" del Google Sheet (ref, direccion) la rellena la
// agencia a mano y se sigue leyendo de ahi.
// ===========================================================================
const MUNICIPIOS = [
  { valor: 'Almazora / Almassora',                       claves: ['almazora', 'almassora'] },
  { valor: 'Alquerías del Niño Perdido',                 claves: ['alquerias', 'alqueries'] },
  { valor: 'Benicasim / Benicàssim',                     claves: ['benicasim', 'benicassim', 'beni'] },
  { valor: 'Borriol',                                    claves: ['borriol'] },
  { valor: 'Burriana / Borriana',                        claves: ['burriana', 'borriana'] },
  { valor: 'Castellón de la Plana / Castelló de la Plana', claves: ['castellon', 'castello'] },
  { valor: 'Onda',                                       claves: ['onda'] },
  { valor: 'Oropesa del Mar / Orpesa',                   claves: ['oropesa', 'orpesa'] },
  { valor: 'Torreblanca',                                claves: ['torreblanca'] },
  { valor: 'Vilafamés',                                  claves: ['vilafames'] },
  { valor: 'Vila-real',                                  claves: ['vila-real', 'villarreal', 'vilareal', 'vila real'] },
];

function normalizarMunicipio(texto) {
  const t = sinAcentos(texto).trim();
  if (!t) return '';
  for (const m of MUNICIPIOS) if (m.claves.some(c => t.includes(c))) return m.valor;
  return '';
}

// Nombre corto para ensenar al cliente: "Castellón", no "Castellón de la Plana / Castelló..."
const municipioCorto = (v) => String(v ?? '').split(' / ')[0].replace(' de la Plana', '');

// Sinonimos de tipo: el cliente dice "casa" y en la hoja pone "Chalet" o "Villa".
const TIPOS = {
  piso:    ['piso', 'apartamento', 'atico', 'duplex', 'estudio', 'planta baja', 'flat'],
  casa:    ['casa', 'chalet', 'villa', 'adosad', 'bungalow', 'finca', 'unifamiliar'],
  atico:   ['atico'],
  local:   ['local', 'oficina', 'nave'],
  terreno: ['terreno', 'parcela', 'solar', 'suelo'],
  garaje:  ['garaje', 'parking', 'plaza'],
  trastero:['trastero'],
};
function casaTipo(pedido, tipoFila) {
  const p = sinAcentos(pedido).trim();
  if (!p) return true;
  const t = sinAcentos(tipoFila);
  const lista = TIPOS[p] || Object.values(TIPOS).find(l => l.some(x => p.includes(x))) || [p];
  return lista.some(x => t.includes(x));
}

const aNumero = (v) => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').replace(/[^\d.,]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : 0;
};

// Alquiler de LARGA DURACION (todo el ano) o TEMPORAL (por meses de invierno,
// p. ej. de septiembre a junio). Lo dice eGO (tipo de negocio 2 = alquiler, 13 =
// alquiler temporal; [WA] 4 lo guarda en wa_cartera.modalidad) y, si no, la
// descripcion. Alquiler de verano no se hace.
function modalidadAlquiler(modalidad, descripcion) {
  const m = String(modalidad ?? '').trim();
  if (m === 'temporal' || m === 'larga_duracion') return m;
  const d = sinAcentos(descripcion).toLowerCase();
  // Primero lo que dice claramente que es temporal ("de temporada", "de septiembre a
  // junio"); "todo el ano" a secas no basta (sale en "luz todo el ano").
  if (/temporada|temporal|no vacacional|por paquete|de (septiembre|octubre|noviembre) (a|hasta)|hasta (final de )?(mayo|junio)/.test(d)) return 'temporal';
  if (/alquiler anual|larga duracion|(alquiler|apartamento|piso|vivienda|casa|vivir) para todo el ano/.test(d)) return 'larga_duracion';
  if (/invierno/.test(d)) return 'temporal';
  return '';
}
const MODALIDAD_TEXTO = {
  larga_duracion: 'alquiler de LARGA DURACION (todo el año)',
  temporal: 'alquiler TEMPORAL (por meses de invierno, no todo el año)',
};

function limpiarFila(r) {
  const operacion = String(r.tipo_transaccion ?? '').toLowerCase().includes('alquil') ? 'alquiler' : 'venta';
  return {
    ref: String(r.ref).trim(),
    precio: aNumero(r.precio),
    operacion,
    modalidad: operacion === 'alquiler' ? modalidadAlquiler(r.modalidad, r.descripcion) : '',
    tipo: String(r.tipo_inmueble ?? '').trim() || 'Inmueble',
    municipio: String(r.municipio ?? '').trim(),
    zona: String(r.zona ?? '').trim(),
    habitaciones: Math.round(aNumero(r.habitaciones)),
    banos: Math.round(aNumero(r.banos)),
    superficie: Math.round(aNumero(r.superficie)),
    caracteristicas: String(r.caracteristicas ?? '').trim(),
    descripcion: String(r.descripcion ?? '').replace(/\s+/g, ' ').trim(),
    imagen: String(r.imagen ?? '').trim(),
    enlace: String(r.enlace ?? '').trim(),
  };
}

function leerCartera(nodo) {
  return $(nodo).all().map(i => i.json).filter(r => r && r.ref).map(limpiarFila);
}

function leerDirecciones(nodo) {
  const dirs = {};
  try {
    for (const it of $(nodo).all()) {
      const j = (it && it.json) ? it.json : {};
      if (j.ref && j.direccion) dirs[String(j.ref).trim().toUpperCase()] = String(j.direccion).trim();
    }
  } catch (e) { /* sin pestana de direcciones: se sigue sin ellas */ }
  return dirs;
}

const euros = (n, operacion) => n
  ? n.toLocaleString('es-ES', { maximumFractionDigits: 0 }) + ' €' + (operacion === 'alquiler' ? '/mes' : '')
  : 'precio a consultar';

// Todo el texto donde buscar extras ("piscina", "vistas al mar"...)
const textoBuscable = (r) => sinAcentos(`${r.tipo} ${r.zona} ${r.caracteristicas} ${r.descripcion}`);

// Una linea por inmueble, para listados
function tarjeta(r, dirs) {
  const partes = [
    `${r.tipo} en ${r.zona ? r.zona + ', ' : ''}${municipioCorto(r.municipio)}`,
    r.habitaciones ? `${r.habitaciones} hab.` : '',
    r.banos ? `${r.banos} baños` : '',
    r.superficie ? `${r.superficie} m²` : '',
    euros(r.precio, r.operacion),
    MODALIDAD_TEXTO[r.modalidad] || '',
    r.encima ? 'POR ENCIMA DE SU PRESUPUESTO' : '',
  ].filter(Boolean);
  const dir = dirs && dirs[r.ref.toUpperCase()];
  const destacado = r.caracteristicas.split(',').map(s => s.trim()).filter(Boolean).slice(0, 3).join(', ');
  return `[${r.ref}] ${partes.join(' · ')}` + (dir ? ` · ${dir}` : '')
    + (destacado ? ` · ${destacado}` : '') + (r.enlace ? ` · ${r.enlace}` : '');
}

// Busca una referencia con la misma tolerancia que el telefono: exacta, luego
// prefijo + numero (se ignoran las letras intermedias y la final), luego solo numero.
function buscarReferencia(filas, texto) {
  const norm = s => String(s ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const partes = s => {
    const n = norm(s);
    const pref = (n.match(/^[A-Z]{2}/) || [''])[0];
    const nums = (n.match(/\d+/g) || []).sort((a, b) => b.length - a.length);
    return { n, pref, num: nums[0] || '' };
  };
  const q = partes(texto);
  if (!q.n) return { filas: [], parecidas: [] };
  const idx = filas.map(r => ({ r, p: partes(r.ref) }));
  let m = idx.filter(x => x.p.n === q.n);
  if (!m.length && q.pref && q.num) m = idx.filter(x => x.p.pref === q.pref && x.p.num === q.num);
  if (!m.length && q.num) m = idx.filter(x => x.p.num === q.num);
  const parecidas = (!m.length && q.pref && q.num)
    ? idx.filter(x => x.p.pref === q.pref && x.p.num.length === q.num.length &&
        [...x.p.num].filter((c, i) => c !== q.num[i]).length === 1).map(x => x.r.ref).slice(0, 3)
    : [];
  return { filas: m.map(x => x.r), parecidas };
}

// La ficha COMPLETA de un inmueble, en texto, tal y como la lee el agente.
function fichaTexto(r, dirs) {
  const dir = dirs && dirs[r.ref.toUpperCase()];
  return [
    `Referencia: ${r.ref}`,
    `Operacion: ${r.operacion === 'alquiler' ? (MODALIDAD_TEXTO[r.modalidad] ? MODALIDAD_TEXTO[r.modalidad].toUpperCase() : 'ALQUILER')
      + ' (no se agenda: se cualifica y se pasa al equipo)' : 'VENTA'}`,
    `Tipo: ${r.tipo}`,
    `Municipio: ${municipioCorto(r.municipio)}`,
    r.zona ? `Zona: ${r.zona}` : '',
    `Direccion: ${dir || 'no consta (no la deduzcas; si la pide, ofrece que se la confirme la asesora)'}`,
    `Precio: ${euros(r.precio, r.operacion)}`,
    r.superficie ? `Superficie: ${r.superficie} m\u00b2` : '',
    r.habitaciones ? `Habitaciones: ${r.habitaciones}` : '',
    r.banos ? `Ba\u00f1os: ${r.banos}` : '',
    r.caracteristicas ? `Caracteristicas: ${r.caracteristicas}` : '',
    r.descripcion ? `Descripcion del anuncio: ${r.descripcion}` : '',
    r.enlace ? `Enlace de la web (se lo puedes mandar): ${r.enlace}` : '',
    `Asesora: ${resolverAsesora(r.ref, r.municipio).destinatario}`,
  ].filter(Boolean).join('\n');
}


// [WA] 4 · Cartera desde eGO · Modalidad
// Cada alquiler, de LARGA DURACION o TEMPORAL. El feed no lo dice; eGO si: el
// tipo de negocio de cada inmueble disponible (2 = alquiler, 13 = alquiler
// temporal), en una sola llamada (ListRealestateByPage). Si eGO no contesta, se
// deduce de la descripcion ("alquiler anual", "temporada de septiembre a junio"...).
const filas = $('Mapear').first().json.filas || [];
let lista = [];
try {
  const d = $('NegociosEgo').first().json.datos || {};
  lista = d.realestatesByPageDto || [];
} catch (e) { lista = []; }
const NEGOCIO = { 2: 'larga_duracion', 13: 'temporal' };
const porRef = {};
for (const x of lista) {
  const negocio = Number(((x.businesses || [])[0] || {}).businessTypeId || 0);
  if (x.reference && NEGOCIO[negocio]) porRef[String(x.reference).toUpperCase().trim()] = NEGOCIO[negocio];
}
const conModalidad = filas.map(f => ({
  ...f,
  modalidad: /alquil/i.test(String(f.tipo_transaccion ?? ''))
    ? (porRef[String(f.ref).toUpperCase().trim()] || modalidadAlquiler('', f.descripcion)) : '',
}));
return [{ json: { filas: conModalidad, de_ego: Object.keys(porRef).length } }];
